<?php $title='Donate & Blood Donation'; require 'config/config.php'; require_login(); if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$pdo->prepare('INSERT INTO donations(user_id,name,email,phone,blood_group,donation_date,location) VALUES(?,?,?,?,?,?,?)');$uid=$_SESSION['member_user']['id']??null;$s->execute([$uid,trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),$_POST['blood_group'],$_POST['donation_date']?:null,trim($_POST['location'])]);flash('success','Thank you. Your donor registration has been received.');header('Location: donate.php');exit;} require 'includes/header.php'; ?><div class="formwrap support-card"><h1>Support the Odynasties Project</h1><p class="muted">Want to support the project financially? Click below to reveal the M-Pesa number. The number can be added later when you are ready.</p><button type="button" class="btn" id="revealDonate">Donate</button><div id="donateNumber" class="donate-number" style="display:none;margin-top:18px;padding:18px;border:1px solid #ddd;border-radius:10px"><strong>M-Pesa Number</strong><div style="font-size:1.35rem;margin-top:8px;letter-spacing:1px"><?= $donation_mpesa_number ? e($donation_mpesa_number) : 'Number to be added' ?></div><p class="muted" style="margin-bottom:0">The final M-Pesa number can be added in <code>config/config.php</code> before the site goes live.</p></div></div>
<div class="formwrap"><h1>Donate & Save Lives</h1><p class="muted">Register your interest in donating blood to support the O community.</p><form method="post"><div class="formgrid"><div class="field"><label>Name</label><input name="name" value="<?=e($_SESSION['member_user']['name']??'')?>" required></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=e($_SESSION['member_user']['email']??'')?>"></div></div><div class="formgrid"><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Blood group</label><select name="blood_group" required><option value="">Select</option><?php foreach(['O+','O-','A+','A-','B+','B-','AB+','AB-'] as $b): ?><option><?=e($b)?></option><?php endforeach; ?></select></div></div><div class="formgrid"><div class="field"><label>Preferred donation date</label><input type="date" name="donation_date"></div><div class="field"><label>Location</label><input name="location" placeholder="Town / facility"></div></div><button class="btn">Register as Donor</button></form></div><script>document.getElementById('revealDonate').addEventListener('click',function(){var box=document.getElementById('donateNumber');box.style.display='block';this.style.display='none';});</script><?php require 'includes/footer.php'; ?>
